/* Golden Braid AIDM B1 S20 Bandit — test cases
FILE: MonsterTestCase_Mentzer_Basic_Bandit_Insert.sql
TARGET: DnD on PEQUOD (SQL Server 2016+)
SOURCE: Mentzer Basic 1983 Dungeon Masters Rulebook, Bandit printed p.25.
B1 S20 is the species selector only; The False Guides is a synthetic fixture.
2026-11-22. Idempotent INSERT-ONLY; Specified/SourceChecked are not execution, approval or UAT.
*/
USE [DnD];
GO
IF OBJECT_ID(N'Test.MonsterTestCase',N'U') IS NULL THROW 57202,'Test.MonsterTestCase missing',1;
IF NOT EXISTS(SELECT 1 FROM [Test].[MonsterTestScenario] WHERE [ScenarioCode]=N'BANDIT-T001') THROW 57203,'BANDIT-T001 missing: deploy scenario first',1;
GO
SET XACT_ABORT ON;
GO
BEGIN TRY
 BEGIN TRAN;
 DECLARE @Seed TABLE ([ScenarioCode] NVARCHAR(MAX) NOT NULL,[TestCaseCode] NVARCHAR(MAX) NOT NULL,[SequenceNo] INT NOT NULL,[TestName] NVARCHAR(MAX) NOT NULL,[TestPhase] NVARCHAR(MAX) NOT NULL,[TestStatus] NVARCHAR(MAX) NOT NULL,[TestRevision] INT NOT NULL,[GivenText] NVARCHAR(MAX) NOT NULL,[ExpectedText] NVARCHAR(MAX) NOT NULL,[DiceFixtureJson] NVARCHAR(MAX) NULL,[AdditionalDataJson] NVARCHAR(MAX) NULL,[LinkedStoryRef] NVARCHAR(MAX) NULL,[AutomatedTestRef] NVARCHAR(MAX) NULL,[Notes] NVARCHAR(MAX) NULL);
 INSERT INTO @Seed ([ScenarioCode],[TestCaseCode],[SequenceNo],[TestName],[TestPhase],[TestStatus],[TestRevision],[GivenText],[ExpectedText],[DiceFixtureJson],[AdditionalDataJson],[LinkedStoryRef],[AutomatedTestRef],[Notes]) VALUES
  (N'BANDIT-T001',N'BND-C01',1,N'1-HD attack row',N'COMBAT',N'Specified',1,N'A Bandit attacks a valid target with an equipped weapon.',N'Resolve exactly one attack using the 1-HD monster attack row; no Thief-level hit bonus.',N'{"attack_d20":15}',N'{"attack_as":"1 HD monster","attacks_per_round":1}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C02',2,N'Sword standard damage',N'COMBAT',N'Specified',1,N'BND-T001-1 hits a valid target using a normal sword in standard damage mode.',N'Use standard 1d6 weapon damage; d6=4 inflicts 4 HP with no extra effect.',N'{"attack_d20":19,"standard_weapon_d6":4}',N'{"expected_damage":4}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C03',3,N'Sword variable weapon damage',N'COMBAT',N'Specified',1,N'BND-T001-2 hits using a normal sword with approved Variable Weapon Damage active.',N'Use the actual sword 1d8; d8=7 inflicts 7 HP. Do not use claw or class damage.',N'{"variable_weapon_d8":7}',N'{"expected_damage":7,"weapon":"sword"}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C04',4,N'Spear weapon damage',N'COMBAT',N'Specified',1,N'BND-T001-3 hits with an equipped spear.',N'Resolve actual equipped spear damage: standard 1d6 or variable spear 1d6; no unsupported charge bonus.',N'{"damage_d6":5}',N'{"expected_damage":5}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C05',5,N'Club variable damage',N'COMBAT',N'Specified',1,N'BND-T001-4 hits with an equipped club while variable damage is active.',N'Use club 1d4 (rolled 3); standard mode remains generic 1d6 if separately selected.',N'{"variable_club_d4":3}',N'{"expected_variable_damage":3}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C06',6,N'Miss deals no damage',N'COMBAT',N'Specified',1,N'A Bandit rolls natural 1 against a target.',N'The attack misses, inflicts zero damage and does not trigger an invented secondary effect.',N'{"attack_d20":1}',N'{"expected_damage":0}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C07',7,N'Independent bandit HP',N'COMBAT',N'Specified',1,N'Four Bandits enter combat from the fixed encounter handoff.',N'Maintain individual starting HP 6,4,5,3; 18 aggregate; no fixed values inferred from B1 stocking.',NULL,N'{"starting_hp":[6,4,5,3],"total_hp":18,"armor_class":6}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C08',8,N'Ordinary initiative ordering',N'COMBAT',N'Specified',1,N'Neither side is surprised; party d6=5 and Bandits d6=2.',N'Use normal per-side initiative; party acts first subject to actual supported delayed-weapon rules, not deception.',N'{"party_initiative_d6":5,"bandits_initiative_d6":2}',N'{"winner":"party"}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C09',9,N'Tied side initiative',N'COMBAT',N'Specified',1,N'Ordinary opposing attacks have matching initiative d6 rolls.',N'Resolve initiative tie simultaneously under established Mentzer Combat rules.',N'{"party_initiative_d6":4,"bandits_initiative_d6":4}',N'{"simultaneous":true}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C10',10,N'No social combat modifier',N'COMBAT',N'Specified',1,N'The Bandits had pretended to be helpful before the handoff but surprise and tactical modifiers are neutral.',N'No attack bonus, automatic surprise or disadvantage merely because of prior bluffing.',NULL,N'{"social_modifier":0,"automatic_surprise":false}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C11',11,N'Successful morale check',N'COMBAT',N'Specified',1,N'A source-supported morale checkpoint occurs and Bandit morale dice total 7.',N'Use morale 8; check succeeds without a forced rout or invented second check.',N'{"morale_2d6":[3,4]}',N'{"morale":8,"check_passed":true}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C12',12,N'Failed morale check',N'COMBAT',N'Specified',1,N'A source-supported morale checkpoint occurs and Bandit morale dice total 9.',N'Morale 8 is failed; return the result for lawful action resolution without a second roll.',N'{"morale_2d6":[4,5]}',N'{"morale":8,"check_passed":false}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C13',13,N'Defeated Bandit cannot attack',N'COMBAT',N'Specified',1,N'BND-T001-4 is reduced to 0 HP before its pending non-simultaneous attack.',N'Apply damage; Bandit can no longer execute its later attack. Tied simultaneous action remains separate.',N'{"incoming_damage":3}',N'{"bandit_hp_end":0,"late_attack_allowed":false}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-C14',14,N'No Thief skill or Backstab',N'COMBAT',N'Specified',1,N'BND-T001-1 saves as Thief 1 and attacks without a separately defined class.',N'Thief 1 determines saving throw table only; no Backstab, Hide in Shadows, Pick Locks or other class effect.',NULL,N'{"save_as":"Thief 1","thief_class_skills":false}',N'AIDM-DES-001.7',NULL,N'Specified only; no tests executed.'),
  (N'BANDIT-T001',N'BND-E01',15,N'Four Bandits generated',N'ENCOUNTER',N'Specified',1,N'S20 Bandit type is selected and count d8=4; HP faces 6,4,5,3.',N'Build four separate 1-HD actors with exactly those HP and 18 aggregate; not B1 preassigned actors.',N'{"count_d8":4,"hp_1d8":[6,4,5,3]}',N'{"count":4,"total_hp":18}',NULL,NULL,N'Future Encounter Engine; not built; no tests executed.'),
  (N'BANDIT-T001',N'BND-E02',16,N'Equipment and speaker are fixture facts',N'ENCOUNTER',N'Specified',1,N'The False Guides scene includes supplies and four Bandits.',N'Keep two swords, one spear and one club; BND-T001-1 is spokesperson but not a higher-level NPC.',NULL,N'{"weapons":["sword","sword","spear","club"],"higher_level_leader":false}',NULL,NULL,N'Future Encounter Engine; not built; no tests executed.'),
  (N'BANDIT-T001',N'BND-E03',17,N'One surprise check per side',N'ENCOUNTER',N'Specified',1,N'Party rolls 5 and Bandits roll 4 when meeting at a passage junction.',N'Neither side is surprised; prior disguise grants no automatic surprise or extra d6.',N'{"party_surprise_d6":5,"bandits_surprise_d6":4}',N'{"party_surprised":false,"bandits_surprised":false}',NULL,NULL,N'Future Encounter Engine; not built; no tests executed.'),
  (N'BANDIT-T001',N'BND-E04',18,N'Surprised-side handoff',N'ENCOUNTER',N'Specified',1,N'Alternate valid branch: party surprise d6=1, Bandit surprise d6=5.',N'Mark party surprised and convey the determined opening to Combat if escalation occurs; do not decide Combat initiative.',N'{"party_surprise_d6":1,"bandits_surprise_d6":5}',N'{"party_surprised":true,"bandits_surprised":false}',NULL,NULL,N'Future Encounter Engine; not built; no tests executed.'),
  (N'BANDIT-T001',N'BND-E05',19,N'Human guise described without forced revelation',N'ENCOUNTER',N'Specified',1,N'The Bandits initially act as ordinary dungeon explorers and offer directions.',N'Narrative reflects observable clothing, weapons, supplies and conversation; concealed intention is not automatically disclosed.',NULL,N'{"may_pose_as_guides":true,"prewritten_dialogue_required":false}',NULL,NULL,N'Future Encounter Engine; not built; no tests executed.'),
  (N'BANDIT-T001',N'BND-E06',20,N'Reaction and negotiation remain encounter',N'ENCOUNTER',N'Specified',1,N'The party talks, challenges the guides or offers to pay for advice.',N'Encounter interprets reactions and dialogue, allows threats, bluffing or negotiation, and never calls Combat merely because Bandits are present.',NULL,N'{"negotiation_allowed":true,"forced_combat":false}',NULL,NULL,N'Future Encounter Engine; not built; no tests executed.'),
  (N'BANDIT-T001',N'BND-E07',21,N'Retreat possible before combat',N'ENCOUNTER',N'Specified',1,N'The party declines directions and withdraws while the Bandits assess their opportunity.',N'Interpret intentions, risks and reactions in Encounter; do not call Combat unless a real fight begins.',NULL,N'{"retreat_possible":true,"automatic_attack":false}',NULL,NULL,N'Future Encounter Engine; not built; no tests executed.'),
  (N'BANDIT-T001',N'BND-E08',22,N'Strict structured combat handoff',N'ENCOUNTER',N'Specified',1,N'The Bandits actually escalate and combat becomes necessary.',N'Send four actors with HP, AC, weapons, positions when known, validated conditions and any confirmed surprise outcome; pass no unresolved bluff or social algorithms to Combat.',NULL,N'{"actor_count":4,"hp":[6,4,5,3],"morale":8,"encounter_logic_in_combat":false}',NULL,NULL,N'Future Encounter Engine; not built; no tests executed.');
 INSERT INTO [Test].[MonsterTestCase] ([ScenarioCode],[TestCaseCode],[SequenceNo],[TestName],[TestPhase],[TestStatus],[TestRevision],[GivenText],[ExpectedText],[DiceFixtureJson],[AdditionalDataJson],[LinkedStoryRef],[AutomatedTestRef],[Notes])
 SELECT s.[ScenarioCode],s.[TestCaseCode],s.[SequenceNo],s.[TestName],s.[TestPhase],s.[TestStatus],s.[TestRevision],s.[GivenText],s.[ExpectedText],s.[DiceFixtureJson],s.[AdditionalDataJson],s.[LinkedStoryRef],s.[AutomatedTestRef],s.[Notes] FROM @Seed AS s
 WHERE NOT EXISTS(SELECT 1 FROM [Test].[MonsterTestCase] AS t WITH(UPDLOCK,HOLDLOCK) WHERE t.[ScenarioCode]=s.[ScenarioCode] AND t.[TestCaseCode]=s.[TestCaseCode]);
 PRINT CONCAT(N'Inserted Bandit test definitions: ',@@ROWCOUNT);
 COMMIT;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK;
 THROW;
END CATCH;
GO
SELECT [ScenarioCode],[TestPhase],[TestStatus],COUNT(*) AS [TestCount] FROM [Test].[MonsterTestCase]
WHERE [ScenarioCode]=N'BANDIT-T001' GROUP BY [ScenarioCode],[TestPhase],[TestStatus]
ORDER BY [TestPhase],[TestStatus];
GO
